{
  "findings": [
    {
      "check_id": "CKV_AWS_364",
      "title": "Lambda invocation permission is not restricted by source account",
      "resource": "aws_lambda_permission.api_gateway_invoke",
      "severity": "MEDIUM",
      "explanation": "The API Gateway service principal can invoke the Lambda function without a SourceArn or SourceAccount condition. Restricting the permission to the current AWS account reduces cross-account confused-deputy risk."
    }
  ],
  "patched_code": "data \"aws_caller_identity\" \"current\" {}\n\nresource \"aws_lambda_permission\" \"api_gateway_invoke\" {\n  statement_id  = \"AllowExecutionFromAPIGateway\"\n  action        = \"lambda:InvokeFunction\"\n  function_name = aws_lambda_function.log_processing_pipeline.function_name\n  principal     = \"apigateway.amazonaws.com\"\n  source_account = data.aws_caller_identity.current.account_id\n}\n",
  "fix_summary": "Added a current-account lookup and constrained the API Gateway Lambda permission with source_account."
}
